use std::cmp::Ordering;
use std::collections::BinaryHeap;

#[derive(Eq, PartialEq)]
struct Item {
    priority: i32,
    value: String,
}

impl Ord for Item {
    fn cmp(&self, other: &Self) -> Ordering {
        other.priority.cmp(&self.priority)
    }
}

impl PartialOrd for Item {
    fn partial_cmp(&self, other: &Self) -> Option<Ordering> {
        Some(self.cmp(other))
    }
}

pub struct StablePriorityQueue {
    heap: BinaryHeap<Item>,
}

impl StablePriorityQueue {
    pub fn new() -> Self {
        StablePriorityQueue { heap: BinaryHeap::new() }
    }

    pub fn push(&mut self, priority: i32, value: &str) {
        self.heap.push(Item { priority, value: value.to_string() });
    }

    pub fn pop(&mut self) -> Option<String> {
        self.heap.pop().map(|i| i.value)
    }
}

impl Default for StablePriorityQueue {
    fn default() -> Self {
        Self::new()
    }
}

