use stable_pq::StablePriorityQueue;

#[test]
fn priority_order() {
    let mut q = StablePriorityQueue::new();
    q.push(5, "low");
    q.push(1, "high");
    q.push(3, "mid");
    assert_eq!(q.pop(), Some("high".to_string()));
    assert_eq!(q.pop(), Some("mid".to_string()));
    assert_eq!(q.pop(), Some("low".to_string()));
}

#[test]
fn equal_priority_is_fifo_across_many_items() {
    let mut q = StablePriorityQueue::new();
    for i in 0..20 {
        let c = ((b'a' + i) as char).to_string();
        q.push(1, &c);
    }
    for i in 0..20 {
        let want = ((b'a' + i) as char).to_string();
        assert_eq!(q.pop(), Some(want));
    }
}

